styles:
.b-cards {
    container-type: inline-size;
    padding-block: var(--site-section-space, var(--site-space-6));
}

.b-cards__head {
    max-width: 42rem;
    margin-bottom: var(--site-section-head-space, var(--site-space-5));
}

.b-cards__eyebrow {
    margin: 0 0 var(--site-eyebrow-space, var(--site-space-2));
    /* Unset, the parent's: font-family and line-height are inherited. */
    font-family: var(--site-eyebrow-font);
    font-size: var(--site-eyebrow-size, var(--site-font-size-6));
    font-weight: var(--site-eyebrow-weight, 600);
    line-height: var(--site-eyebrow-line-height);
    letter-spacing: var(--site-eyebrow-letter-spacing, 0.08em);
    text-transform: var(--site-eyebrow-case, uppercase);
}

.b-cards__heading {
    margin: 0 0 var(--site-section-title-space, var(--site-space-2));
}

/* The section's H2 type (THEMES §7.2): unset, the prose's own, and only where the prose applies
   (in the main column and under site-prose), so that nothing changes until a site sets it. */
.b-cards__heading:where(.site-main *, .site-prose *) {
    font-family: var(--site-section-title-font, var(--site-font-heading));
    font-size: var(--site-section-title-size, var(--site-font-size-2));
    line-height: var(--site-section-title-line-height, 1.2);
    /* Unset, nothing: an inherited property falls back to the parent's. */
    text-transform: var(--site-section-title-case);
}

.b-cards__intro {
    margin: 0;
    color: var(--site-color-text-muted);
}

.b-cards__grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: var(--site-space-4);
    margin: 0;
    padding: 0;
    list-style: none;
}

.b-cards__card {
    position: relative;
    display: flex;
    flex-direction: column;
    margin: 0;
    overflow: hidden;
    border: 1px solid var(--site-color-border);
    border-radius: var(--site-radius-lg);
    background: var(--site-color-surface);
    color: var(--site-color-text);
    transition: border-color var(--site-duration) var(--site-easing), box-shadow var(--site-duration) var(--site-easing);
}

.b-cards__card.is-linked:hover {
    border-color: var(--site-color-accent);
    box-shadow: var(--site-shadow-md);
}

.b-cards--photo .b-cards__picture {
    width: 100%;
    max-width: none;
    height: auto;
    aspect-ratio: 3 / 2;
    border-radius: 0;
    object-fit: cover;
}

/* Several photos: the same frame as one, the photos changing in it. */
.b-cards__photos {
    flex: none;
}

.b-cards--icon .b-cards__picture {
    width: 3rem;
    height: 3rem;
    margin: var(--site-space-5) var(--site-space-5) 0;
    border-radius: 0;
    object-fit: contain;
}

.b-cards__body {
    display: flex;
    flex: 1;
    flex-direction: column;
    gap: var(--site-space-2);
    padding: var(--site-space-5);
}

.b-cards__title {
    margin: 0;
    font-size: var(--site-font-size-4);
    line-height: 1.3;
    hyphens: auto;
}

.b-cards__link {
    color: inherit;
    text-decoration: none;
}

/* The whole card is the link: the title's box stretched over it, so there is one link to
   tab to and one name for a screen reader. */
.b-cards__link::after {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
}

.b-cards__link:focus-visible {
    outline: none;
}

.b-cards__link:focus-visible::after {
    outline: 2px solid var(--site-color-accent);
    outline-offset: -2px;
}

/* Labels: short words in a row that wraps, quieter than the text. */
.b-cards__chips {
    display: flex;
    flex-wrap: wrap;
    gap: var(--site-space-1);
    margin: 0;
    padding: 0;
    list-style: none;
}

.b-cards__chip {
    margin: 0;
    padding: var(--site-space-1) var(--site-space-2);
    border-radius: var(--site-radius-full);
    background: var(--site-color-surface-muted);
    color: var(--site-color-text-muted);
    /* Smaller than the text: the scale of the theme has no step below it. */
    font-size: 0.875em;
    line-height: 1.3;
}

.b-cards__text {
    margin: 0;
    color: var(--site-color-text-muted);
}

.b-cards__more {
    display: flex;
    align-items: center;
    gap: var(--site-space-1);
    margin-top: auto;
    padding-top: var(--site-space-2);
    color: var(--site-color-accent);
    font-weight: 600;
}

.b-cards__arrow {
    transition: transform var(--site-duration) var(--site-easing);
}

.b-cards__card.is-linked:hover .b-cards__arrow {
    transform: translateX(0.25em);
}

/* In the carousel the cards of a row are as tall as the tallest, as in the grid. */
.b-cards__carousel .webx-slider__slide {
    display: flex;
    height: auto;
}

.b-cards__carousel .b-cards__card {
    flex: 1;
    min-width: 0;
}

@container (min-width: 32rem) {
    .b-cards__grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@container (min-width: 52rem) {
    .b-cards--3 .b-cards__grid,
    .b-cards--4 .b-cards__grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}

@container (min-width: 64rem) {
    .b-cards--4 .b-cards__grid {
        grid-template-columns: repeat(4, minmax(0, 1fr));
    }
}

/* The section's button, under the words of the head. */
.b-cards__actions {
    display: flex;
    flex-wrap: wrap;
    gap: var(--site-space-3);
    margin-top: var(--site-section-actions-space, var(--site-space-5));
}

.b-cards__button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 44px;
    padding: 0 var(--site-space-5);
    border: 1px solid transparent;
    border-radius: var(--site-radius-md);
    background: var(--site-color-accent);
    color: var(--site-color-accent-contrast);
    font-weight: 600;
    line-height: 1.2;
    text-align: center;
    text-decoration: none;
    transition: background-color var(--site-duration) var(--site-easing);
}

.b-cards__button:hover {
    background: color-mix(in srgb, var(--site-color-accent) 85%, var(--site-color-text));
}

.b-cards__button:focus-visible {
    outline: 2px solid var(--site-color-accent);
    outline-offset: 2px;
}

/* The photo under the whole card (`pictures: overlay`), the words on a pane of glass over its foot.
   The block's own variables are the knobs a site's theme turns: the card's shape, the pane's
   margin, padding and spacing, how clear the glass is. */
.b-cards--overlay,
.b-cards--split {
    /* Named: inside a carousel the nearest container is the slider, and the queries below mean the section. */
    container-name: b-cards;
}

.b-cards--overlay {
    --cards-ratio: 3 / 4;
    --cards-split-ratio: 4 / 3;
    --cards-plate-margin: var(--site-space-4);
    --cards-plate-padding: var(--site-space-6);
    --cards-plate-gap: var(--site-space-5);
    --cards-plate-actions-space: var(--site-space-5);
    --cards-plate-glass: 72%;
    --cards-plate-glass-solid: 92%;
    --cards-plate-blur: 16px;
}

.b-cards--overlay .b-cards__card {
    display: grid;
    grid-template: minmax(0, 1fr) auto / minmax(0, 1fr);
    aspect-ratio: var(--cards-ratio);
    border: 0;
    background: var(--site-color-surface-muted);
}

/* The photo, or the photos turning, fill the card: both rows of its grid. */
.b-cards--overlay .b-cards__picture,
.b-cards--overlay .b-cards__photos {
    grid-area: 1 / 1 / 3 / 2;
    width: 100%;
    max-width: none;
    height: 100%;
    border-radius: 0;
    object-fit: cover;
}

.b-cards--overlay .webx-photos__frame {
    height: 100%;
    aspect-ratio: auto;
}

/* The pane is not positioned: the title's link stretched over the card keeps the card as its box,
   while the pane's z-index lifts it, and the link with it, over the photo. */
.b-cards--overlay .b-cards__body {
    z-index: 1;
    grid-area: 2 / 1;
    flex: none;
    gap: var(--cards-plate-gap);
    margin: var(--cards-plate-margin);
    padding: var(--cards-plate-padding);
    border-radius: var(--site-radius-md);
    background: color-mix(in srgb, var(--site-color-surface) var(--cards-plate-glass), transparent);
    color: var(--site-color-text);
    -webkit-backdrop-filter: blur(var(--cards-plate-blur));
    backdrop-filter: blur(var(--cards-plate-blur));
}

/* Without the blur the photo would show through sharp: a denser pane instead. */
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
    .b-cards--overlay .b-cards__body {
        background: color-mix(in srgb, var(--site-color-surface) var(--cards-plate-glass-solid), transparent);
    }
}

/* The bars of the photos stand in the pane's foot, over the card's link: a click on a bar turns
   the photo and opens nothing. The pause button keeps its corner over the link too. Without the
   script there are no bars, and no room is kept for them. */
.b-cards--overlay .b-cards__card:has(.webx-photos.is-ready) .b-cards__body {
    padding-bottom: calc(var(--cards-plate-padding) + 24px);
}

.b-cards--overlay .webx-photos__bars {
    inset-inline: calc(var(--cards-plate-margin) + var(--cards-plate-padding));
    bottom: calc(var(--cards-plate-margin) + var(--cards-plate-padding) / 2);
    z-index: 2;
    --webx-photos-bar-color: color-mix(in srgb, var(--site-color-text) 20%, transparent);
    --webx-photos-bar-current: color-mix(in srgb, var(--site-color-text) 30%, transparent);
    --webx-photos-fill-color: var(--site-color-text);
}

.b-cards--overlay .webx-photos__fill {
    box-shadow: none;
}

.b-cards--overlay .webx-photos__pause {
    z-index: 2;
}

.b-cards--overlay .b-cards__title {
    font-size: var(--site-font-size-4);
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.b-cards--overlay .b-cards__text {
    color: var(--site-color-text);
}

.b-cards--overlay .b-cards__chip {
    background: color-mix(in srgb, var(--site-color-surface) 70%, transparent);
}

/* The link words are a button here: an outline in the words' colour. */
.b-cards--overlay .b-cards__more {
    align-self: flex-start;
    min-height: 44px;
    margin-top: calc(var(--cards-plate-actions-space) - var(--cards-plate-gap));
    padding: 0 var(--site-space-5);
    border: 1px solid currentColor;
    border-radius: var(--site-radius-md);
    color: var(--site-color-text);
}

.b-cards--overlay .b-cards__card.is-linked:hover .b-cards__more {
    background: var(--site-color-text);
    color: var(--site-color-surface);
}

/* The words beside a carousel of one card (`view: split`): side by side while the column has room
   for both, the words above where it has not — by wrapping, so no query of the section's own width
   is needed. The bars under the slide are the slider's pagination, drawn as lines. */
.b-cards--split {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--site-section-head-space, var(--site-space-5)) var(--site-space-7);
}

.b-cards--split > .b-cards__head {
    flex: 5 1 18rem;
    margin-bottom: 0;
}

.b-cards--split > .b-cards__carousel {
    flex: 7 1 26rem;
    min-width: 0;
}

/* Beside the words the card is wide; above them, on a phone, it stays tall for its pane. */
@container b-cards (min-width: 40em) {
    .b-cards--split.b-cards--overlay .b-cards__card {
        aspect-ratio: var(--cards-split-ratio);
    }
}

.b-cards--split .webx-slider__pagination {
    flex: 1 1 auto;
    flex-wrap: nowrap;
    gap: var(--site-space-1);
}

.b-cards--split .webx-slider__bullet {
    flex: 1 1 0;
    width: auto;
    min-width: 24px;
}

.b-cards--split .webx-slider__bullet::before {
    width: 100%;
    height: 3px;
}

/* Beside the words with the photo under them (`split` + `overlay`): one pane of glass over the
   carousel, out of its track, so it stands still while the photos turn under it. The slider's
   overlay holds it; the words of every card are in it, the current one in view and the change a
   crossfade; the lines under them are the slider's pagination. The words inside the slides are
   what shows without the script, and they give way to the pane once it is there. */
.b-cards--plated {
    --cards-plate-fade: 400ms;
    --cards-bars-space: var(--site-space-5);
    --cards-bar-width: 32px;
    --cards-bar-height: 3px;
    --cards-bar-gap: var(--site-space-2);
    --cards-bar-color: color-mix(in srgb, var(--site-color-text) 20%, transparent);
    --cards-bar-current: var(--site-color-text);
}

.b-cards--plated .webx-slider {
    --webx-slider-caption-fade: var(--cards-plate-fade);
}

.b-cards--plated .webx-slider__overlay {
    align-self: end;
    margin: var(--cards-plate-margin);
}

/* The slides fill the slider's cell: a pane taller than the photo makes the photo taller, it does
   not run past it. */
.b-cards--plated .webx-slider.is-ready .webx-slider__track {
    height: 100%;
}

.b-cards--plated .webx-slider.is-ready .webx-slider__slide .b-cards__body {
    display: none;
}

/* Positioned: the title's link stretched over the pane, not over the photos it would keep from a swipe. */
.b-cards__plate {
    position: relative;
    display: flex;
    flex-direction: column;
    gap: var(--cards-bars-space);
    padding: var(--cards-plate-padding);
    border-radius: var(--site-radius-md);
    background: color-mix(in srgb, var(--site-color-surface) var(--cards-plate-glass), transparent);
    color: var(--site-color-text);
    -webkit-backdrop-filter: blur(var(--cards-plate-blur));
    backdrop-filter: blur(var(--cards-plate-blur));
}

@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
    .b-cards__plate {
        background: color-mix(in srgb, var(--site-color-surface) var(--cards-plate-glass-solid), transparent);
    }
}

/* The words of a card in the pane: the pane is the glass, not each of them. */
.b-cards--plated .b-cards__plate .b-cards__body {
    margin: 0;
    padding: 0;
    border-radius: 0;
    background: none;
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
}

.b-cards--plated .b-cards__plate-item:has(.b-cards__link):hover .b-cards__more {
    background: var(--site-color-text);
    color: var(--site-color-surface);
}

/* The lines: short, in a row at the start, over the title's link. */
.b-cards--plated .b-cards__bars {
    position: relative;
    z-index: 1;
    flex: none;
    flex-wrap: nowrap;
    justify-content: flex-start;
    gap: var(--cards-bar-gap);
}

.b-cards--plated .b-cards__bars .webx-slider__bullet {
    flex: 0 1 var(--cards-bar-width);
    width: var(--cards-bar-width);
    min-width: 24px;
    height: 24px;
}

.b-cards--plated .b-cards__bars .webx-slider__bullet::before {
    width: 100%;
    height: var(--cards-bar-height);
    border-radius: var(--site-radius-full);
    background: var(--cards-bar-color);
}

.b-cards--plated .b-cards__bars .webx-slider__bullet.is-active::before {
    background: var(--cards-bar-current);
}

/* Several photos of a card turn under the pane: their bars at the photo's top, clear of it. */
.b-cards--plated .webx-slider.is-ready .webx-photos__bars {
    top: var(--cards-plate-margin);
    bottom: auto;
    inset-inline: var(--cards-plate-margin);
}

/* On a narrow screen the carousels and the photo cards run to the screen's sides, square: the
   section stands in the main column, whose gutters they cover. Only a direct child of the main
   column; anywhere else the column is what it is. */
@container b-cards (max-width: 39.99em) {
    .b-cards--split:where(.site-main > *) > .b-cards__carousel,
    .b-cards--overlay:where(.site-main > *) > .b-cards__carousel,
    .b-cards--overlay:where(.site-main > *) > .b-cards__grid {
        margin-inline: calc(-1 * var(--site-section-gutter, var(--site-gutter)));
    }

    .b-cards--split:where(.site-main > *) > .b-cards__carousel {
        flex-basis: calc(100% + 2 * var(--site-section-gutter, var(--site-gutter)));
    }

    .b-cards--split:where(.site-main > *) .b-cards__card,
    .b-cards--overlay:where(.site-main > *) .b-cards__card {
        border-radius: 0;
    }

    /* The controls keep to the column. */
    .b-cards--split:where(.site-main > *) .webx-slider__controls,
    .b-cards--overlay:where(.site-main > *) .webx-slider__controls {
        padding-inline: var(--site-section-gutter, var(--site-gutter));
    }
}
